<script setup lang="ts">
import { ArrowRight, Building2, CheckCircle2, Eye, EyeOff, ShieldCheck } from '@lucide/vue'
import { onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import api from '../api'
import { useAuthStore } from '../stores/auth'
import BrandLogo from '../components/BrandLogo.vue'
const route=useRoute(),router=useRouter(),auth=useAuthStore();const token=String(route.query.token||'');const loading=ref(true),saving=ref(false),visible=ref(false),error=ref('');const invitation=ref<any>(null);const form=reactive({name:'',password:'',password_confirmation:''})
onMounted(async()=>{try{const {data}=await api.get('/invitations/accept',{params:{token}});invitation.value=data.invitation;form.name=data.invitation.name}catch(e:any){error.value=e.response?.data?.message||'This invitation is invalid or has expired.'}finally{loading.value=false}})
async function accept(){saving.value=true;error.value='';try{const {data}=await api.post('/invitations/accept',{token,...form});auth.user=data.user;if(data.csrf_token)api.defaults.headers.common['X-CSRF-TOKEN']=data.csrf_token;router.replace('/dashboard')}catch(e:any){error.value=Object.values(e.response?.data?.errors||{error:[e.response?.data?.message||'Unable to accept this invitation.']}).flat().join(' ')}finally{saving.value=false}}
</script>
<template><main class="auth-layout invite-accept"><section class="auth-story"><BrandLogo light/><div class="story-copy"><span class="eyebrow light">A PLACE ON THE TEAM</span><h1>Great teaching<br><em>works together.</em></h1><p>Join one secure workspace with exactly the centres and tools you need.</p><ul><li><CheckCircle2/>Centre-specific access</li><li><CheckCircle2/>A clear role and permissions</li><li><CheckCircle2/>Your own secure account</li></ul></div><footer>ACADEMYHUB <span>INVITATION PROTECTED</span></footer></section><section class="auth-panel"><div class="auth-box"><div v-if="loading" class="invite-loading"><span></span>Checking your invitation…</div><template v-else-if="invitation"><span class="eyebrow">YOU’RE INVITED</span><h2>Welcome to the team.</h2><p>{{invitation.organization.name_en||invitation.organization.name_ar}} invited you to join as {{invitation.role.name}}.</p><div class="invite-summary"><span><ShieldCheck/></span><div><small>YOUR ACCESS</small><b>{{invitation.role.name}}</b><p><Building2/>{{invitation.branches.map((b:any)=>b.name_en||b.name_ar).join(' · ')}}</p></div></div><form @submit.prevent="accept"><label>Your full name<input v-model="form.name" required autocomplete="name"></label><label>Create password<div class="password-field"><input v-model="form.password" :type="visible?'text':'password'" required autocomplete="new-password" placeholder="8+ letters and numbers"><button type="button" @click="visible=!visible"><EyeOff v-if="visible"/><Eye v-else/></button></div></label><label>Confirm password<input v-model="form.password_confirmation" type="password" required autocomplete="new-password"></label><div v-if="error" class="form-error">{{error}}</div><button class="button primary wide" :disabled="saving">{{saving?'Joining workspace…':'Accept and join'}}<ArrowRight/></button></form><small class="fine-print">This invitation verifies {{invitation.email}} and can be used once.</small></template><template v-else><span class="eyebrow">INVITATION UNAVAILABLE</span><h2>This link can’t be used.</h2><p>{{error}}</p><RouterLink to="/login" class="button secondary wide">Return to sign in</RouterLink></template></div></section></main></template>
